var l89Trace = {errors: [], nullCommands: []};
var l89LogError = LogError;
LogError = function(src) {
  l89Trace.errors.push({message: String(src), stack: src && src.stack || null,
    phase: currentPhase.title, identifier: currentPhase.identifier});
  return l89LogError.apply(this, arguments);
};
var l89ExecuteChosen = ExecuteChosen;
ExecuteChosen = function(cmd) {
  if (cmd == null) l89Trace.nullCommands.push({phase: currentPhase.title, identifier: currentPhase.identifier,
    side: activePlayer === corp ? 'corp' : 'runner', executingCommand: executingCommand,
    commands: EnumeratePhase(), resolving: corp.resolvingCards.map(function(c) {return c.title;})});
  return l89ExecuteChosen.apply(this, arguments);
};
__report = function() {return l89Trace;};

