const fs = require('fs');
const root = process.cwd();
const batch = require(root+'/scripts/ai-batch');
const {playGame} = require(root+'/scripts/ai-batch/headless');
const [pairId,seed] = process.argv.slice(2);
const config = batch.buildConfig(batch.parseArgs(['--pool','tests/fixtures/ai-batch/deck-pool.json','--pairs',pairId,'--seeds',seed+'-'+seed,'--jobs','1','--defense-observer','off','--corp-option','postureEpochs=true','--corp-option','matchLocalPostureFeedback=true','--collector','realizedIceByRootType','--collector','bluffSingleVariableCorrelation','--collector','installOutcomes']));
const collectors=config.collectorNames.map(n=>require(root+'/scripts/ai-batch/collectors/'+n));
const states=collectors.map(()=>({seed,deckPairId:pairId,fixtureId:null}));
const events=[];
playGame({streamPrefix:seed+':'+pairId,corpFile:config.pairs[0].corp,runnerFile:config.pairs[0].runner,setFiles:config.setFiles,timeoutMs:config.timeoutMs,corpOptions:config.corpOptions,runnerOptions:config.runnerOptions,securityCache:config.securityCache,realizedDefenseSnapshot:false,defenseObserver:'off',telemetry:true,observe:true,fullLog:true,tail:200,setupFile:'/tmp/L8.9-trace-setup.js',onEvent:e=>{events.push(e);collectors.forEach((c,i)=>c.onEvent(Object.freeze({...e}),states[i]));}}).then(game=>{
 fs.writeFileSync(root+'/bench/L8.9-aac6ea9-stage1-diagnostics/'+pairId+'-'+seed+'-trace-off.json',JSON.stringify({diagnosticOnly:true,setupFile:'/tmp/L8.9-trace-setup.js',collectors:config.collectorNames,game,events},null,2)+'\n');
 process.exitCode=game.errors.length || !game.winner ? 1:0;
});
